package com.vaijunto.domain.entities;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.CreationTimestamp; import org.hibernate.annotations.UpdateTimestamp; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="notification_device_tokens") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class NotificationDeviceToken { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; @Column(nullable=false,unique=true,length=512) private String token; @CreationTimestamp @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @UpdateTimestamp @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt; }
